import logging

from taf.hw.optical_switch.devices.base import OpticalSwitch
from taf.hw.optical_switch.devices.clients.http_client import HttpClient
from taf.hw.optical_switch.exceptions import InvalidInput, OpticalSwitchResponseError


class HttpOpticalSwitch(OpticalSwitch):
    """Class that makes it possible to
    manage a single http session"""

    def __init__(
        self, addr, port=80, protocol="http", user_name="", password="", timeout=5
    ):
        super().__init__(host=addr, port=port, timeout=timeout)
        self.http_client = HttpClient(
            user_name, password, addr, port, timeout, f"{protocol}://{addr}:{port}"
        )

    def teardown(self):
        self.http_client.disconnect()

    def _validate_settings(self, settings):
        if not isinstance(settings, dict):
            raise InvalidInput("Input should be dictionary!")
        logging.debug(f"Input:{settings}")

    @staticmethod
    def _check_response_status_code_equal_200(response):
        if response.status_code != 200:
            exc_msg = (f"Unrecognized response from the server.\n"
                       f"Status: {response.status_code}.\nText: '{response.text}'")
            raise OpticalSwitchResponseError(exc_msg)
